#!/bin/bash
# Run after verified flash. Only host tooling/configuration; no PS payload upload.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd);out=$(realpath -m "$1");matrix=$(realpath "$2");bin=$(realpath "$3");manifest=$(realpath "$4");[[ $out == "$HOME/sc7f0/"* && ! -e $out ]];mkdir "$out";cd "$out"
( exec 9<>"$HOME/sc7f0/tmp/.upgrade.lock";flock -n 9;ctl(){ sudo -n "$HOME/sc7f0/bin/sc7f0ctl" --timeout 60 exec "$1"; }; paths=$(awk '{print $2}' "$manifest"|xargs);ctl "sha256sum $paths" >cold.sha256;cmp "$manifest" cold.sha256;ctl 'set -e;systemctl is-active sc7f0-vcud sc7f0-modetest qpcie-debugd qpcie-upgrade-daemon qpcie-hdmi-daemon;systemctl show sc7f0-vcud -p ExecStart -p DropInPaths -p FragmentPath;readlink -f /proc/$(systemctl show sc7f0-vcud -p MainPID --value)/exe;cat /proc/sys/kernel/random/boot_id;ls -l /dev/sc7f0-stage2;modetest -M xlnx -p | head -40' >cold-state;grep -qx 'DropInPaths=' cold-state;grep -qx /usr/bin/sc7f0_vcud cold-state; )
for rate in cbr vbr;do python3 "$here/selected_avc.py" "$matrix/summary.tsv" "$rate" >"$rate.range";done
for spec in 'avc cbr audit' 'hevc cbr ball60' 'avc cbr irregular' 'avc vbr irregular';do read -r codec rate kind <<<"$spec";r=$(cat "$rate.range");k=$codec-$rate-$kind;bash "$here/capture-leg.sh" "$bin" "$out/$k" "$codec" "$rate" "$r" "$kind" >"$k.log" 2>&1;(cd "$k";python3 "$here/check_recording.py" >inspection.log;if [[ $kind == ball60 ]];then python3 "$here/display_cadence.py" flips.log >display.json;fi;sha256sum host.es trace events dq decode.md5 result.json runtime setup restore-card >MANIFEST.sha256);done
